// Optimization: vectorized 16-byte float4 streaming loads. Each batch's
// (D1, D2) plane is treated as one flat float4 array (a short scalar
// head/tail fixes pointer alignment and divisibility), so all loads are
// fully aligned and coalesced regardless of whether D2 is odd. A thread's
// float4-group stride T is a multiple of D2/gcd(4, D2), which keeps
// (head + 4*g) mod D2 invariant, so every thread owns a fixed set of 4
// output columns. Partial maxima are merged with a single round of
// order-preserving unsigned atomicMax per thread, bracketed by tiny
// init/unmap passes over the (B, D2) output.
__device__ __forceinline__ unsigned int f2u_ordered(float f) {
    unsigned int u = __float_as_uint(f);
    return (u & 0x80000000u) ? ~u : (u | 0x80000000u);
}
__device__ __forceinline__ float u2f_ordered(unsigned int u) {
    u = (u & 0x80000000u) ? (u & 0x7FFFFFFFu) : ~u;
    return __uint_as_float(u);
}
__global__ void init_out_kernel(float* __restrict__ out, long long n) {
    const long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = __uint_as_float(0x007FFFFFu);  // ordered(-inf)
}
__global__ void unmap_out_kernel(float* __restrict__ out, long long n) {
    const long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = u2f_ordered(__float_as_uint(out[i]));
