__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int D1, int D2) {
    const int b = blockIdx.y;
    const long long L = (long long)D1 * D2;
    const float* base = x + (long long)b * L;
    const int mis = (int)(((uintptr_t)base >> 2) & 3);
    long long head = (4 - mis) & 3;
    if (head > L) head = L;
    const long long nv4 = (L - head) >> 2;
    const long long tail = (L - head) - 4 * nv4;
    const int h = (D2 % 4 == 0) ? 4 : ((D2 % 2 == 0) ? 2 : 1);
    const long long T = D2 / h;  // group stride preserving column phase
    const long long t0 = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    float* ob = out + (long long)b * D2;
    if (t0 == 0 && blockIdx.z == 0) {
        for (long long e = 0; e < head; ++e) {
            const int col = (int)(e % D2);
            atomicMax((unsigned int*)(ob + col), f2u_ordered(__ldcs(base + e)));
        }
        for (long long e = 0; e < tail; ++e) {
            const long long pos = L - tail + e;
            const int col = (int)(pos % D2);
            atomicMax((unsigned int*)(ob + col), f2u_ordered(__ldcs(base + pos)));
        }
    }
    if (t0 >= T) return;
    const float4* base4 = reinterpret_cast<const float4*>(base + head);
    const long long chunk = (nv4 + (long long)gridDim.z - 1) / (long long)gridDim.z;
    const long long g0 = chunk * (long long)blockIdx.z + t0;
    long long gend = chunk * (long long)(blockIdx.z + 1);
    if (gend > nv4) gend = nv4;
    if (g0 >= gend) return;
    const int r = (int)((head + 4 * g0) % D2);
    int c1 = r + 1; while (c1 >= D2) c1 -= D2;
    int c2 = r + 2; while (c2 >= D2) c2 -= D2;
    int c3 = r + 3; while (c3 >= D2) c3 -= D2;
