        const float4 v2 = __ldcs(base4 + g + 2 * T);
        const float4 v3 = __ldcs(base4 + g + 3 * T);
        const float4 v4 = __ldcs(base4 + g + 4 * T);
        const float4 v5 = __ldcs(base4 + g + 5 * T);
        const float4 v6 = __ldcs(base4 + g + 6 * T);
        const float4 v7 = __ldcs(base4 + g + 7 * T);
        a0 = fmaxf(a0, fmaxf(fmaxf(fmaxf(v0.x, v1.x), fmaxf(v2.x, v3.x)), fmaxf(fmaxf(v4.x, v5.x), fmaxf(v6.x, v7.x))));
        a1 = fmaxf(a1, fmaxf(fmaxf(fmaxf(v0.y, v1.y), fmaxf(v2.y, v3.y)), fmaxf(fmaxf(v4.y, v5.y), fmaxf(v6.y, v7.y))));
        a2 = fmaxf(a2, fmaxf(fmaxf(fmaxf(v0.z, v1.z), fmaxf(v2.z, v3.z)), fmaxf(fmaxf(v4.z, v5.z), fmaxf(v6.z, v7.z))));
