    }
    for (; g < gend; g += T) {
        const float4 v = __ldcs(base4 + g);
        a0 = fmaxf(a0, v.x);
        a1 = fmaxf(a1, v.y);
        a2 = fmaxf(a2, v.z);
        a3 = fmaxf(a3, v.w);
    }
    atomicMax((unsigned int*)(ob + r),  f2u_ordered(a0));
    atomicMax((unsigned int*)(ob + c1), f2u_ordered(a1));
    atomicMax((unsigned int*)(ob + c2), f2u_ordered(a2));
    atomicMax((unsigned int*)(ob + c3), f2u_ordered(a3));
