    init_out_kernel<<<nblk, tpb, 0, stream>>>(out.data_ptr<float>(), n);
    const int h = (D2 % 4 == 0) ? 4 : ((D2 % 2 == 0) ? 2 : 1);
    const long long T = D2 / h;
    const long long nv4_est = (((long long)D1 * D2) + 3) >> 2;
    const long long groups_per_col = (T > 0) ? (nv4_est / T) : 0;
    unsigned int zs = 1;
