    }
    dim3 grid((unsigned int)((T + tpb - 1) / tpb), (unsigned int)B, zs);
    max_reduce_dim1_kernel<<<grid, tpb, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), D1, D2);
    unmap_out_kernel<<<nblk, tpb, 0, stream>>>(out.data_ptr<float>(), n);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
